-- 芯慧联芯 纳入研究池 (2026-10-15)
INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'芯慧联芯',null,'semiconductor','equipment',false,'增资扩股',null,null,null,'2026-06','{"name":"芯慧联芯","industry":"semiconductor","seg":"equipment","listed":false,"desc":"芯慧联芯（江苏）控股有限公司，2024-02 由苏州芯慧联半导体科技有限公司（WST，2019-01 成立，董事长兼总经理刘红军创立）将晶圆键合（Wafer Bonding）业务派生分立而来，总部无锡锡山/锡东新城，实控人刘红军。公司定位「三维集成技术解决方案提供商」，主营半导体先进键合设备 —— W2W（晶圆到晶圆）与 D2W（芯片到晶圆）混合键合（Hybrid Bonder）、熔融键合（Fusion Bonder）设备，以及配套量检测、解键合等附属设备，提供键合工艺流程全套业务，产品应用于集成电路晶圆制造、先进存储与先进封装领域，是混合键合设备国产替代的代表性厂商。核心技术全部正向自研，实现 100% 全流程工艺自研，研发人员占比 60%，建有百级洁净室；CANOPUS 系列混合键合设备一体化集成预对准、实时对准、活化、清洗、量测与解键合等模块，具备高精度键合、实时对准与智能键合控制特征。键合强度、键合界面缺陷、对准精度、微扭曲等核心指标在测试厂商中排名前列。2024-11 首台 W2W Hybrid Bonder 与首台 D2W Hybrid Bonder 交付，同年 12 月首台 W2W Fusion Bonder 交付；2025-12 设备交付多个行业头部客户并获复购订单。公司在无锡锡东新城建设集成电路工艺设备研发制造基地（总投资 50 亿元，一期 2026 年 6 月投产，规划年产 300 台半导体核心设备），并与中科院、无锡学院共建联合创新中心。母公司芯慧联系列布局还覆盖涂胶显影、湿法清洗、静电卡盘、EFEM 与机械手等设备。百傲化学（603360.SH）通过全资子公司上海芯傲华科技有限公司间接持股，为其少数股东。荣誉：2025 年度中国集成电路创新百强企业、中国半导体设备创新十强企业、无锡市「首台套」装备、高新技术企业、科技型中小企业。","round":"增资扩股","lastFunding":"2026-06","latestFunding":"2026-06 · 增资扩股 2 亿元：合肥启航恒鑫投资基金出资 5,000 万元，其关联后续投资人可再出资 1.5 亿元，合计 2 亿元；另新设员工持股平台芯耀达（181 万元）、芯辰达（643.5686 万元）同步增资。本轮按市场化估值定价，百傲化学及其他原有股东放弃优先认购权，持股比例由 10.1439% 降至 8.4851%。","latestTech":"CANOPUS 系列 W2W/D2W 混合键合设备基于正向设计自主研发，关键性能指标达国际同类产品领先水平，可一体化集成预对准、实时对准、活化、清洗、量测和解键合等多种模块，具备高精度键合、实时对准、智能键合控制等特征，支持高度定制化和模块自主可控；已实现熔融及混合先进键合设备全覆盖。","tech":[{"date":"2025-12","title":"混合键合设备交付多个行业头部客户并获复购订单","kind":"量产","desc":"W2W/D2W 混合键合设备进入批量交付阶段，客户覆盖国内封测与 IDM 厂商。"},{"date":"2024-11","title":"首台 W2W 与 D2W 混合键合设备交付","kind":"量产","desc":"首台 W2W Hybrid Bonder 与首台 D2W Hybrid Bonder 正式出厂交付，打破该设备国内市场长期空白。"},{"date":"2022-01","title":"首台 W2W 混合键合设备原型机下线","kind":"研发","desc":"芯慧联体系内启动 W2W/D2W 混合键合设备研发（2020-04）后，首台 W2W Fusion/Hybrid Bonder 原型机下线。"}],"funding":[{"date":"2026-06","round":"增资扩股","amount":"2亿元","inv":"合肥启航恒鑫投资基金合伙企业（有限合伙）（5000万元，其关联后续投资人可再出资1.5亿元）；员工持股平台上海芯耀达企业管理合伙企业（181万元）、上海芯辰达企业管理合伙企业（643.5686万元）"},{"date":"2026-04","round":"股权激励","inv":"员工持股平台上海芯信达企业管理合伙企业（有限合伙）（因股权激励计划考核指标完成增资）"},{"date":"2025-01","round":"Pre-A轮","inv":"未披露"}],"investorsStructured":[{"name":"合肥启航恒鑫投资基金","role":"lead","round":"增资扩股","date":"2026-06","kind":"pe","note":"合肥国资背景基金，本轮出资 5000 万元"},{"name":"上海芯耀达企业管理合伙企业","role":"other","round":"增资扩股","date":"2026-06","kind":"other","note":"新设员工持股平台，由实控人刘红军控制"},{"name":"上海芯辰达企业管理合伙企业","role":"other","round":"增资扩股","date":"2026-06","kind":"other","note":"新设员工持股平台，由实控人刘红军控制"},{"name":"上海芯信达企业管理合伙企业","role":"other","round":"股权激励","date":"2026-04","kind":"other","note":"员工持股平台"},{"name":"上海芯傲华科技有限公司","role":"strategic","round":"早期","date":"2024","kind":"cvc","note":"百傲化学（603360.SH）全资子公司，间接持股 10.1439%（2026-06 增资后降至 8.4851%）"}],"executives":[{"name":"刘红军","title":"董事长","role":"board","bio":"1970年生，河海大学自动化专业毕业，曾参与我国首条6英寸晶圆生产线建设，国家首批公派赴日学习芯片产线技术；曾任首钢日电、东电电子（上海）、东电光电半导体设备（昆山）、北京亦盛精密半导体等企业高管；2019年创立芯慧联半导体科技，现任芯慧联芯实际控制人、董事长，并任百傲化学（603360.SH）总经理。"},{"name":"任潮群","title":"总经理","role":"management","bio":"芯慧联芯总经理，主导公司键合设备业务运营与技术战略。"}],"note":"2024-02 由苏州芯慧联半导体科技有限公司（WST）派生分立，键合业务独立运营；实控人刘红军同时担任百傲化学（603360.SH）总经理，百傲化学通过芯傲华间接持股。关联企业：芯慧联（面板刻蚀/湿法设备，佛山华南总部）、芯慧联新（苏州）。"}'::jsonb,now()
)
